<template>
  <div class="v3-course v3-screen" data-node-id="6006:28045">
    <sf-page-layout title="Courses" :ambient="false" @back="$emit('action','back')"><template #trailing><button type="button" class="sf-icon-button sf-icon-button--compact" aria-label="Share course" @click="share=true"><img :src="asset('img6')" alt="" data-source-asset="true"></button></template>
      <div class="v3-course__hero"><img :src="content.coverUrl||asset('imgPexelsAndreaPiacquadio3757944')" alt="" data-source-asset="true"><div class="v3-course__coach"><img :src="asset('img1')" alt="" data-source-asset="true"><div><strong>Bernice Nelson Yos</strong><small>Course coach</small></div><sf-button compact :block="false" @click="toggleFollow">{{ preferences.following?'Following':'Follow' }}</sf-button></div><span v-if="accessLabel" class="v3-course__access commerce-content-label">{{ accessLabel }}</span></div>
      <div class="v3-course__actions"><button type="button" @click="share=true"><img :src="asset('imgFriend')" alt="" data-source-asset="true"><span>Invite</span></button><button type="button" @click="calendar=true"><img :src="asset('img5')" alt="" data-source-asset="true"><span>Calendar</span></button><button type="button" :aria-pressed="preferences.favorite?'true':'false'" @click="toggleFavorite"><img :src="asset('imgFavorFill')" alt="" data-source-asset="true"><span>{{ preferences.favorite?'Favorited':'Favorite' }}</span></button></div>
      <section class="v3-course__identity" data-testid="course-identity"><h2 data-testid="course-title">{{ content.name }}</h2><p data-testid="course-description">{{ content.description }}</p><p v-if="preferences.date" class="v3-course__scheduled">Scheduled {{ preferences.date }}</p></section>
      <dl class="v3-course__metrics" data-testid="course-metrics"><div v-for="metric in metrics" :key="metric.label"><dt>{{ metric.label }}</dt><dd :data-testid="metric.label==='Duration'?'course-duration':null">{{ metric.value }}</dd></div></dl>
      <mvp-access-note :content="content" @action="$emit('action',$event)"/>
      <section class="v3-course__details" data-testid="course-details"><h3>Course preview</h3><div class="v3-course__previews"><article v-for="preview in previews" :key="preview.title"><header><h4>{{ preview.title }}</h4><img :src="asset(preview.icon)" alt="" data-source-asset="true"></header><img :src="asset(preview.image)" :alt="preview.title+' reference preview'" data-source-asset="true"></article></div></section>
      <template #footer><div class="v3-course__footer" data-testid="course-footer"><button type="button" class="v3-course__music" aria-label="Audio preference" @click="openAudio"><img :src="asset('img14')" alt="" data-source-asset="true"><span>Music</span></button><sf-button data-action="start-course" :data-content-id="content.id" @click.stop="$emit('action','start-course:'+content.id)">Start</sf-button></div></template>
    </sf-page-layout>
    <sf-sheet v-model="share" title="Invite to this course" contained :resizable="false"><p class="v3-course__sheet-copy">{{ content.name }}</p><label class="v3-course__share-label" for="course-share-link">Course link</label><input id="course-share-link" class="v3-course__share-input" :value="shareLink" readonly @focus="$event.target.select()"><p v-if="copyFeedback" role="status">{{ copyFeedback }}</p><template #footer><sf-button @click="copyLink">Copy link</sf-button></template></sf-sheet>
    <sf-sheet v-model="calendar" title="Schedule workout" contained :resizable="false"><sf-field v-model="draftDate" type="date" label="Workout date" help="Saved on this device."/><template #footer><sf-button :disabled="!draftDate" @click="saveDate">Save date</sf-button></template></sf-sheet>
    <sf-sheet v-model="audio" title="Audio preference" contained :resizable="false"><sf-choice v-model="draftAudio" type="radio" name="course-audio" option="course" label="Course audio"/><sf-choice v-model="draftAudio" type="radio" name="course-audio" option="mute" label="Muted"/><template #footer><sf-button @click="saveAudio">Save preference</sf-button></template></sf-sheet>
  </div>
</template>
<script>
import {SfPageLayout,SfButton,SfIcon,SfSheet,SfField,SfChoice} from '@/design-system'
import {sceneAsset} from '@/design-system/assets/v3-scenes'
import MvpAccessNote from './MvpAccessNote'
export default {name:'V3Course',components:{MvpAccessNote,SfPageLayout,SfButton,SfIcon,SfSheet,SfField,SfChoice},props:{content:{type:Object,required:true},user:Object,accessLabel:String},data(){return {preferences:{favorite:false,following:false,date:'',audio:'course'},draftDate:'',draftAudio:'course',share:false,calendar:false,audio:false,copyFeedback:''}},computed:{metrics(){return [{label:'Workout type',value:'Trainer-led'},{label:'Duration',value:this.content.durationMinutes+' min'},{label:'Calorie',value:this.content.calories!=null?this.content.calories+' kcal':'—'},{label:'Equipment',value:this.content.equipment||'—'},{label:'Joined',value:this.content.joinedCount!=null?String(this.content.joinedCount):'—'},{label:'Average Speed',value:this.content.averageSpeed||'—'}]},previews(){return [{title:'Warmup',image:'img10',icon:'img9'},{title:'Cooldown',image:'img12',icon:'img11'}]},preferenceKey(){return 'sunnyfit-demo:v3-course:'+((this.user&&this.user.id)||'local')+':'+this.content.id},shareLink(){return location.origin+location.pathname+'#/app/course?'+new URLSearchParams({content:this.content.id,review:'0'})}},watch:{preferenceKey:{immediate:true,handler(){this.preferences={favorite:false,following:false,date:'',audio:'course'};try{const saved=JSON.parse(localStorage.getItem(this.preferenceKey));if(saved)this.preferences={...this.preferences,...saved}}catch(_){}this.draftDate=this.preferences.date}}},methods:{asset(name){return sceneAsset('course',name)},savePreferences(){try{localStorage.setItem(this.preferenceKey,JSON.stringify(this.preferences))}catch(_){}},toggleFavorite(){this.preferences.favorite=!this.preferences.favorite;this.savePreferences()},toggleFollow(){this.preferences.following=!this.preferences.following;this.savePreferences()},saveDate(){this.preferences.date=this.draftDate;this.savePreferences();this.calendar=false},openAudio(){this.draftAudio=this.preferences.audio;this.audio=true},saveAudio(){this.preferences.audio=this.draftAudio;this.savePreferences();this.audio=false},async copyLink(){try{await navigator.clipboard.writeText(this.shareLink);this.copyFeedback='Link copied.'}catch(_){this.copyFeedback='Select the link to copy it.'}}}}
</script>
